def hidden_rule_fn(state):
    rows = len(state)
    cols = len(state[0])
    next_state = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            s = state[r][c]
            # Compute diagonal tetrad counts with toroidal wrap
            d_z = 0
            d_p = 0
            d_q = 0
            for dr in [-1, 1]:
                for dc in [-1, 1]:
                    nr = (r + dr) % rows
                    nc = (c + dc) % cols
                    val = state[nr][nc]
                    if val == 0:
                        d_z += 1
                    elif val == 1:
                        d_p += 1
                    elif val == 2:
                        d_q += 1

            if s == 0:
                # ZORK: if all 4 diagonals are QUAV (impossible since only 4 diagonals), next=2
                # Actually d_q==3 means 3 QUAVs in diagonal tetrad
                if d_q == 3:
                    next_state[r][c] = 2
                elif d_p == 2:
                    next_state[r][c] = 1
                else:
                    next_state[r][c] = 0
            elif s == 1:
                # PLOON: if d_p (count of PLOON neighbors) is odd, next=2; else next=1
                if d_p % 2 == 1:
                    next_state[r][c] = 2
                else:
                    next_state[r][c] = 1
            elif s == 2:
                # QUAV: next=2 unless d_z==3 or (d_z==2 and d_p==0)
                if d_z <= 1:
                    next_state[r][c] = 2
                elif d_z == 2 and d_p > 0:
                    next_state[r][c] = 2
                else:
                    next_state[r][c] = 1

    return next_state
